div.script:
{
        "@context": "https://schema.org",
        "@type": "FAQPage",
        "mainEntity": [
          {"@type": "Question", "name": "How long does delivery take?", "acceptedAnswer": {"@type": "Answer", "text": "Phnom Penh and Ta Khmau: same or next day. Provinces: 2-4 working days via VET or J&T Express."}},
          {"@type": "Question", "name": "How much does shipping cost?", "acceptedAnswer": {"@type": "Answer", "text": "Flat $1.50 in Phnom Penh, $2.50 to provinces, free on orders over $35."}},
          {"@type": "Question", "name": "How do I track my order?", "acceptedAnswer": {"@type": "Answer", "text": "Tracking numbers are sent by SMS or Telegram as soon as the parcel ships; customer care is available at 031 266 3333."}},
          {"@type": "Question", "name": "What is your return policy?", "acceptedAnswer": {"@type": "Answer", "text": "Unopened products can be returned within 14 days for a full refund. Damaged items are replaced free within 48 hours of delivery."}},
          {"@type": "Question", "name": "Are ABJ products cruelty-free?", "acceptedAnswer": {"@type": "Answer", "text": "Yes, ABJ products are never tested on animals."}}
        ]
      }

(function(){
  function apply(l, store){
    document.documentElement.classList.toggle('abj-km', l==='km');
    var bs=document.querySelectorAll('.abj-langswitch button');
    for(var i=0;i<bs.length;i++){bs[i].classList.toggle('active', bs[i].getAttribute('data-lang')===l);}
    if(store){try{localStorage.setItem('abjLang', l);}catch(e){}}
  }
  var chosen=null;
  try{chosen=localStorage.getItem('abjLang');}catch(e){}
  var docKm=((document.documentElement.getAttribute('lang')||'').toLowerCase().indexOf('km')===0)||(window.location.pathname.indexOf('/km')===0);
  apply(chosen||(docKm?'km':'en'), false);
  var bs=document.querySelectorAll('.abj-langswitch button');
  for(var i=0;i<bs.length;i++){
    bs[i].addEventListener('click', function(){apply(this.getAttribute('data-lang'), true);});
  }
})();
